/**
 * Whether a ZH/EN heading pair carries the 概述/Overview collision: a ZH
 * `## 概述` that is the existing *Overview* heading (positional pair with
 * the EN `## Overview`), NOT a Summary the generator inserted. For these
 * pairs the generator cannot insert a separate Summary `## 概述` without
 * colliding the `#概述` slug (shared by Summary and the Overview prose) and
 * producing a ZH/EN asymmetry (EN inserts `## Summary` because EN's
 * `## Overview` ≠ `Summary`). F3 SKIPS these pairs for a manual retrofit
 * pass; see `retrofitPair`. Returns false when there is no ZH sibling
 * (zhHeadings is empty) or no positional 概述↔Overview match.
 */
function hasGaiSuOverviewCollision(pair: PairPlan): boolean {
  if (pair.zhHeadings.length === 0) return false
  for (let i = 0; i < pair.zhHeadings.length; i++) {
    const zh = pair.zhHeadings[i]
    const en = pair.enHeadings[i]
    if (zh === undefined || en === undefined) continue
    if (zh === ZH_HEADINGS.summary && en === 'Overview') return true
  }
  return false
}

